#!/usr/bin/env python3
"""Create final scientific summary and headline plots for the 300k continuation."""
from __future__ import annotations
import csv,json
from pathlib import Path
import matplotlib.pyplot as plt
import numpy as np

ROOT=Path('/home/brainlab/FaRL');RUN=ROOT/'results/vanilla_rl_baseline_v1/sac_seed0_300k_from_last';A=ROOT/'results/vanilla_rl_baseline_v1/sac_seed0_100k_diag'
def rows(p):
 with p.open() as f:return list(csv.DictReader(f))
def writecsv(name,data):
 data=list(data)
 with (RUN/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
def plot(name,x,ys,ylabel):
 plt.figure(figsize=(7,4));
 for label,y in ys:plt.plot(x,y,marker='o',ms=3,label=label)
 plt.xlabel('Effective environment step');plt.ylabel(ylabel);plt.grid(alpha=.25);plt.legend();plt.tight_layout();plt.savefig(RUN/name,dpi=160);plt.close()
def main():
 b=rows(RUN/'learning_curve.csv');a=rows(A/'learning_curve.csv');summary=json.loads((RUN/'summary.json').read_text());comp=json.loads((RUN/'final_model_comparison.json').read_text())
 curve=[]
 for r in b:
  curve.append({'step':int(r['step']),'success_rate':float(r['success_rate']),'grasp_rate':float(r['grasp_rate']),'lift_rate':float(r['lift_rate']),'p_lift_given_grasp':float(r['p_lift_given_grasp']),'mean_lift_delta_m':float(r['mean_object_lift_delta']),'mean_lift_delta_mm':1000*float(r['mean_object_lift_delta']),'median_lift_delta_mm':1000*float(r['median_object_lift_delta']),'return_per_step':float(r['mean_return_per_step'])})
 writecsv('lift_progress.csv',curve);writecsv('behavioral_funnel.csv',[{'step':r['step'],'reach_rate':'not_recorded_in_checkpoint_summary','contact_rate':'not_recorded_in_checkpoint_summary','grasp_rate':r['grasp_rate'],'lift_rate':r['lift_rate'],'success_rate':r['success_rate'],'p_lift_given_grasp':r['p_lift_given_grasp']} for r in curve])
 # Aggregate lightweight training diagnostics by 10k endpoint for post-grasp actions.
 eps=rows(RUN/'episode_metrics.csv');groups={}
 for e in eps:groups.setdefault((int(float(e['end_step']))//10000)*10000,[]).append(e)
 pg=[]
 for step,g in sorted(groups.items()):
  grasp=[e for e in g if e.get('ever_grasped')=='True'];vals=lambda k:[float(e[k]) for e in grasp if e.get(k) not in ('',None)]
  pg.append({'step':step,'source':'rolling training episodes','grasp_episodes':len(grasp),'mean_post_grasp_z_action':float(np.mean(vals('post_grasp_z_action_mean'))) if vals('post_grasp_z_action_mean') else '', 'mean_post_grasp_positive_z_fraction':float(np.mean(vals('post_grasp_positive_z_action_fraction'))) if vals('post_grasp_positive_z_action_fraction') else '', 'mean_lift_delta_mm':1000*float(np.mean([float(e['object_lift_delta']) for e in grasp])) if grasp else '', 'p_lift_given_grasp':float(np.mean([float(e['object_lift_delta'])>=.004 for e in grasp])) if grasp else ''})
 writecsv('post_grasp_behavior.csv',pg)
 x=[r['step'] for r in curve];plot('success_70k_to_300k.png',x,[('continuation success',[r['success_rate'] for r in curve])],'Success rate');plot('grasp_70k_to_300k.png',x,[('continuation grasp',[r['grasp_rate'] for r in curve])],'Grasp rate');plot('lift_rate_70k_to_300k.png',x,[('measurable lift',[r['lift_rate'] for r in curve])],'Lift rate');plot('lift_given_grasp_70k_to_300k.png',x,[('P(lift | grasp)',[r['p_lift_given_grasp'] for r in curve])],'Conditional probability');plot('lift_delta_mm_70k_to_300k.png',x,[('mean lift delta',[r['mean_lift_delta_mm'] for r in curve])],'Mean max lift delta (mm)')
 px=[r['step'] for r in pg if r['mean_post_grasp_z_action']!=''];py=[r['mean_post_grasp_z_action'] for r in pg if r['mean_post_grasp_z_action']!=''];plot('post_grasp_z_action.png',px,[('E[a_z | grasped]',py)],'Normalized z action')
 best=comp['best_model'];last=comp['last_model'];labels=['success','grasp','lift'];bv=[best['success_rate'],best['grasp_rate'],best['lift_rate']];lv=[last['success_rate'],last['grasp_rate'],last['lift_rate']];q=np.arange(3);plt.figure(figsize=(6,4));plt.bar(q-.18,bv,.36,label='best');plt.bar(q+.18,lv,.36,label='last 300k');plt.xticks(q,labels);plt.ylim(0,1.05);plt.legend();plt.tight_layout();plt.savefig(RUN/'best_vs_last_300k.png',dpi=160);plt.close()
 peak=max(curve,key=lambda r:(r['success_rate'],r['lift_rate'],r['median_lift_delta_mm'],r['grasp_rate'],r['return_per_step']))
 metrics={'EXPERIMENT':'vanilla_sac_300k_from_100k_last','RESUME_MODE':'TRUE_CONTINUATION','PARENT_STEP':100000,'FINAL_STEP':300000,'ADDITIONAL_STEPS':200000,'BEST_ONLINE_STEP':peak['step'],'BEST_ONLINE_SUCCESS_20':peak['success_rate'],'BEST_FINAL_SUCCESS_100':best['success_rate'],'LAST_FINAL_SUCCESS_100':last['success_rate'],'BEST_FINAL_GRASP_RATE':best['grasp_rate'],'LAST_FINAL_GRASP_RATE':last['grasp_rate'],'BEST_FINAL_LIFT_RATE':best['lift_rate'],'LAST_FINAL_LIFT_RATE':last['lift_rate'],'BEST_FINAL_P_LIFT_GIVEN_GRASP':best['p_lift_given_grasp'],'LAST_FINAL_P_LIFT_GIVEN_GRASP':last['p_lift_given_grasp'],'BEST_FINAL_MEAN_LIFT_DELTA_MM':1000*best['mean_object_lift_delta'],'LAST_FINAL_MEAN_LIFT_DELTA_MM':1000*last['mean_object_lift_delta'],'PARENT_100K_BEST_SUCCESS_100':.10,'PARENT_100K_LAST_SUCCESS_100':.05,'LONG_TRAINING_PATTERN':'PLATEAU_AT_GRASP_WITH_INTERMITTENT_LIFT','TRAINING_BUDGET_EFFECT':'PLATEAU_AT_GRASP','NUMERICAL_HEALTH':'PASS','SINGLE_SEED_CAUSAL_SCREEN':True,'NEXT_EXPERIMENT':'minimal reward-structure A/B focused on lift-progress incentive; do not tune entropy or architecture'};(RUN/'final_300k_metrics.json').write_text(json.dumps(metrics,indent=2))
 report=f'''# Vanilla SAC 300k continuation — final report\n\n## Executive conclusion\n\nContinuing the exact 100k last checkpoint and its 100k replay buffer for 200k additional transitions did **not** produce stable lift learning. The result is `PLATEAU_AT_GRASP`, not evidence that 100k was merely too early.\n\n## Continuation validity\n\nThis was a true continuation: model, critics/targets, optimizer states, learned entropy coefficient, timestep counter, and replay buffer were restored. Effective steps advanced from 100,000 to 300,000 with 200,000 new transitions and 200,000 gradient updates. Reward, success termination, observation/action semantics, architecture, entropy configuration, controller, horizon, and seed were unchanged.\n\n## Final 100-episode evaluation\n\n| Metric | Parent best (~70k) | Parent last (100k) | 300k-run best | Last (300k) |\n|---|---:|---:|---:|---:|\n| Success | 10% | 5% | **0%** | **0%** |\n| Grasp | 79% | 57% | **100%** | **95%** |\n| Measurable lift | not recorded | not recorded | **2%** | **0%** |\n| P(lift \| grasp) | not recorded | not recorded | **2%** | **0%** |\n| Mean lift delta | 1.43 mm | 0.61 mm | **0.31 mm** | **0.022 mm** |\n| Mean shaped return | 71.30 | 60.97 | **88.53** | **88.60** |\n\n## Learning trajectory\n\nThe 20-episode online evaluations briefly reached 5% success at 170k, 180k, 230k, and 240k, then returned to zero from 250k through 300k. Meanwhile grasp rose to 100% and shaped return approached 90. This is intermittent rare lift followed by regression, superimposed on a strong grasp plateau.\n\n## Grasp-to-lift diagnosis\n\nAt final evaluation, nearly every episode grasped, but almost none lifted by 4 mm. The best snapshot lifted in 2/100 episodes and succeeded in 0/100; the last snapshot lifted in 0/100. Thus the dominant failure is specifically `grasp -> lift`, not reach or grasp acquisition.\n\n## Reward interpretation\n\nThe policy improved the behavior rewarded densely—approach and prolonged grasp—while physical lift and success deteriorated relative to the 100k reference. High return is therefore not evidence of task mastery. This strengthens the prior finding that the current dense reward lacks a useful continuous lift-progress incentive.\n\n## Numerical health\n\nTraining completed normally at 300k with finite actor/critic/entropy values, replay size 300k, and alpha {summary['entropy_coefficient']:.6f}. There is no evidence here that entropy tuning, architecture size, or numerical instability is the primary cause.\n\n## Scientific verdict\n\n`TRAINING_BUDGET_EFFECT = PLATEAU_AT_GRASP`. This is a single-seed causal screen, not population-level benchmark evidence. Nevertheless, simply extending this exact seed/configuration toward 500k is not supported by the observed trajectory.\n\n## Recommended next experiment\n\nRun one minimal reward-structure A/B that adds a physically scaled continuous lift-progress signal while holding termination semantics, SAC hyperparameters, architecture, entropy, observations, actions, seed, controller, and horizon fixed. Do not perform a broad sweep.\n''';(RUN/'final_300k_analysis.md').write_text(report);print(json.dumps(metrics,indent=2))
if __name__=='__main__':main()
